export function getNeighborhoodsByCluster(cluster: SchoolCluster): Neighborhood[] {
  return neighborhoods.filter(n => n.schoolCluster === cluster);
}

export function getNeighborhoodById(id: string): Neighborhood | undefined {
  return neighborhoods.find(n => n.id === id);
}
